    #[tokio::test]
    async fn explain_uses_expression_ndistinct_for_stats_ext_group_rows() {
        use assert2::assert;

        let engine = SqlEngine::new();
        let mut s = engine.connect();
        s.simple_query(
            "CREATE TABLE group_expression_estimate (filler1 text, filler2 numeric, a int4, b int4, filler3 date, c int4, d int4); \
             INSERT INTO group_expression_estimate (a, b, c, filler1) \
             SELECT i / 100, i / 100, i / 100, (i / 100)::text FROM generate_series(1, 1000) s(i); \
             ANALYZE group_expression_estimate",
        )
        .await
        .expect("expression ndistinct statistics setup");
        let fallback_statistics = rows_or_sqlstate(
            &mut s,
            "EXPLAIN SELECT count(*) FROM group_expression_estimate GROUP BY (a + 1), (b + 100)",
        )
        .await
        .expect("expression fallback explain");
        assert!(
            fallback_statistics.first().and_then(|row| row.first())
                == Some(&"HashAggregate (cost=0.00..0.00 rows=100 width=0)".into())
        );
        s.simple_query(
            "CREATE STATISTICS group_expression_estimate_stats ON a, b, c FROM group_expression_estimate; \
             ANALYZE group_expression_estimate",
        )
        .await
        .expect("attribute statistics setup");
        let attribute_statistics = rows_or_sqlstate(
            &mut s,
            "EXPLAIN SELECT count(*) FROM group_expression_estimate GROUP BY (a + 1), (b + 100), (2 * c)",
        )
        .await
        .expect("attribute statistics explain");
        assert!(
            attribute_statistics.first().and_then(|row| row.first())
                == Some(&"HashAggregate (cost=0.00..0.00 rows=11 width=0)".into())
        );
        let partial_statistics = rows_or_sqlstate(
            &mut s,
            "EXPLAIN SELECT count(*) FROM group_expression_estimate GROUP BY a, b, c, d",
        )
        .await
        .expect("partial attribute statistics explain");
        assert!(
            partial_statistics.first().and_then(|row| row.first())
                == Some(&"HashAggregate (cost=0.00..0.00 rows=200 width=0)".into())
        );
        s.simple_query(
            "TRUNCATE group_expression_estimate; \
             INSERT INTO group_expression_estimate (a, b, c, filler1) \
             SELECT mod(i, 13), mod(i, 17), mod(i, 19), (mod(i, 23))::text FROM generate_series(1, 1000) s(i); \
             ANALYZE group_expression_estimate; \
             DROP STATISTICS group_expression_estimate_stats; \
             CREATE STATISTICS group_expression_estimate_stats (ndistinct) \
             ON (a + 1), (b + 100), (2 * c) FROM group_expression_estimate; \
             ANALYZE group_expression_estimate",
        )
        .await
        .expect("expression ndistinct statistics refresh");
        for (sql, rows) in [
            (
                "EXPLAIN ANALYZE SELECT count(*) FROM group_expression_estimate GROUP BY (a+1), (b+100)",
                221,
            ),
            (
                "EXPLAIN ANALYZE SELECT count(*) FROM group_expression_estimate GROUP BY (a+1), (b+100), (2*c)",
                1000,
            ),
            (
                "EXPLAIN ANALYZE SELECT count(*) FROM group_expression_estimate GROUP BY a, (a+1), (b+100)",
                221,
            ),
        ] {
            let explain = rows_or_sqlstate(&mut s, sql)
                .await
                .expect("expression ndistinct explain");
            assert!(
                explain
                    .first()
                    .and_then(|row| row.first())
                    .is_some_and(|line| line.starts_with(&format!(
                        "HashAggregate (cost=0.00..0.00 rows={rows} width=0)"
                    ))),
                "{sql}"
            );
        }
        s.simple_query(
            r#"CREATE FUNCTION group_expression_rows(text) RETURNS TABLE (estimated int, actual int)
               LANGUAGE plpgsql AS $$
               DECLARE line text;
               BEGIN
                   FOR line IN EXECUTE format('EXPLAIN ANALYZE %s', $1) LOOP
                       RETURN QUERY SELECT (regexp_match(line, 'rows=(\d*) .* rows=(\d*)'))[1]::int,
                                           (regexp_match(line, 'rows=(\d*) .* rows=(\d*)'))[2]::int;
                       RETURN;
                   END LOOP;
               END;
               $$"#,
        )
        .await
        .expect("dynamic explain function setup");
        assert!(
            rows_or_sqlstate(
                &mut s,
                "SELECT * FROM group_expression_rows('SELECT count(*) FROM group_expression_estimate GROUP BY (a+1), (b+100)')",
            )
            .await
                == Ok(vec![vec!["221".into(), "221".into()]])
        );
    }

    #[tokio::test]
    async fn explain_uses_extended_mcv_for_equality_conjunctions() {
        use assert2::assert;

        let engine = SqlEngine::new();
        let mut s = engine.connect();
        s.simple_query(
            "CREATE TABLE mcv_estimate (a int4, b int4); \
             INSERT INTO mcv_estimate \
             SELECT 1, 1 FROM generate_series(1, 40); \
             INSERT INTO mcv_estimate \
             SELECT 1, 2 FROM generate_series(1, 10); \
             INSERT INTO mcv_estimate \
             SELECT 2, 1 FROM generate_series(1, 10); \
             INSERT INTO mcv_estimate \
             SELECT 2, 2 FROM generate_series(1, 40); \
             CREATE STATISTICS mcv_estimate_ab (mcv) ON a, b FROM mcv_estimate; \
             ANALYZE mcv_estimate",
        )
        .await
        .expect("statistics setup");
        assert!(
            rows_or_sqlstate(
                &mut s,
                "EXPLAIN SELECT * FROM mcv_estimate WHERE a = 1 AND b = 1",
            )
            .await
                == Ok(vec![
                    vec!["Seq Scan on mcv_estimate (cost=0.00..0.00 rows=40 width=0)".into()],
                    vec!["  Filter: ((a = 1) AND (b = 1))".into()],
                ])
        );
        let rows = rows_or_sqlstate(
            &mut s,
            "EXPLAIN SELECT * FROM mcv_estimate WHERE a = 1 OR b = 1",
        )
        .await
        .expect("MCV disjunction explain");
        assert!(
            rows.first()
                == Some(&vec![
                    "Seq Scan on mcv_estimate (cost=0.00..0.00 rows=60 width=0)".into()
                ])
        );
        for sql in [
            "EXPLAIN SELECT * FROM mcv_estimate WHERE a IN (1, 2) AND b = 1",
            "EXPLAIN SELECT * FROM mcv_estimate WHERE (a = 1 OR a = 2) AND b = 1",
            "EXPLAIN SELECT * FROM mcv_estimate WHERE a = ANY (ARRAY[1, 2]) AND b = 1",
        ] {
            let rows = rows_or_sqlstate(&mut s, sql).await.expect("MCV explain");
            assert!(
                rows.first()
                    == Some(&vec![
                        "Seq Scan on mcv_estimate (cost=0.00..0.00 rows=50 width=0)".into()
                    ]),
                "{sql}"
            );
        }
        s.simple_query(
            "CREATE STATISTICS mcv_estimate_expr (mcv) \
             ON (a + b), (a - b) FROM mcv_estimate; ANALYZE mcv_estimate",
        )
        .await
        .expect("expression MCV setup");
        let rows = rows_or_sqlstate(
            &mut s,
            "EXPLAIN SELECT * FROM mcv_estimate WHERE (a + b) = 2 AND (a - b) = 0",
        )
        .await
        .expect("expression MCV explain");
        assert!(
            rows.first()
                == Some(&vec![
                    "Seq Scan on mcv_estimate (cost=0.00..0.00 rows=40 width=0)".into()
                ])
        );
    }

