    #[tokio::test]
    async fn the_utility_bucket_maps_or_refuses_with_postgres_sqlstates() {
        use assert2::assert;
        let engine = SqlEngine::new();
        let mut s = engine.connect();
        s.simple_query("CREATE TABLE t (id int4)")
            .await
            .expect("ddl");
        for sql in [
            "CHECKPOINT",
            "ANALYZE",
            "ANALYZE t (id)",
            "CLUSTER",
            "REINDEX TABLE t",
            "SET CONSTRAINTS ALL DEFERRED",
            "SET SESSION AUTHORIZATION DEFAULT",
            "RESET SESSION AUTHORIZATION",
            "ALTER SYSTEM SET work_mem = '8MB'",
            "ALTER SYSTEM RESET ALL",
            "LOAD 'regress'",
            "DISCARD PLANS",
            "DISCARD SEQUENCES",
            "DISCARD TEMP",
            "DISCARD ALL",
        ] {
            assert!(sqlstate(&mut s, sql).await == "00000", "{sql}");
        }
        assert!(sqlstate(&mut s, "ALTER SYSTEM SET no_such_parameter = 1").await == "42704");
        for (sql, expected) in [
            ("CREATE STATISTICS st ON id FROM t", "0A000"),
            ("ALTER STATISTICS st SET STATISTICS 100", "42704"),
            ("DROP STATISTICS st", "42704"),
        ] {
            assert!(sqlstate(&mut s, sql).await == expected, "{sql}");
        }
        let error = s
            .simple_query("LOAD 'nosuchfile'")
            .await
            .expect_err("missing shared object");
        assert!(error.code == "58P01", "{error:?}");
        assert!(
            error.message == "could not access file \"nosuchfile\": No such file or directory",
            "{error:?}"
        );
        let executable = std::env::current_exe().expect("current executable");
        let sql = format!("LOAD '{}'", executable.display());
        assert!(sqlstate(&mut s, &sql).await == "0A000", "{sql}");
        let error = s
            .simple_query("LOAD '/definitely/missing/regress.so'")
            .await
            .expect_err("an unconfigured regress basename is not trusted");
        assert!(error.code == "58P01", "{error:?}");
        s.simple_query("BEGIN").await.expect("begin");
        assert!(sqlstate(&mut s, "DISCARD ALL").await == "25001");
        s.simple_query("ROLLBACK").await.expect("rollback");
    }

