    #[tokio::test]
    async fn empty_extended_sql_is_rejected_inside_failed_transaction_until_rollback() {
        let engine = SqlEngine::new();
        let mut session = engine.connect();

        session.simple_query("BEGIN").await.expect("begin");
        let original_error = session
            .simple_query("SELECT * FROM missing_table")
            .await
            .expect_err("undefined table aborts explicit transaction");
        assert_eq!(original_error.code, "42P01");

        let execute_error = session
            .test_extended_query("", &[])
            .await
            .expect_err("empty extended execute is rejected in failed transaction");
        assert_eq!(execute_error.code, "25P02");

        let describe_error = session
            .test_describe_prepared("", &[])
            .await
            .expect_err("empty extended prepare/describe is rejected in failed transaction");
        assert_eq!(describe_error.code, "25P02");

        session.simple_query("ROLLBACK").await.expect("rollback");
        session
            .test_extended_query("", &[])
            .await
            .expect("rollback restores empty extended execute behavior");
        session
            .test_describe_prepared("", &[])
            .await
            .expect("rollback restores empty extended describe behavior");
        let selected = session
            .simple_query("SELECT 1")
            .await
            .expect("rollback restores session usability");
        assert_eq!(single_text(&selected), "1");
    }

    /// SP37: `SET TIME ZONE` flows through the GUC into `eval_ctx()`, so a
    /// `timestamptz` renders in the session zone; `SHOW timezone` reads it back;
    /// and a ROLLBACK reverts a `SET` made inside a transaction.
    #[tokio::test]
    async fn set_timezone_flows_into_rendering_and_show() {
        let engine = SqlEngine::new();
        let mut s = engine.connect();

        // Default zone is UTC.
        let show = s.simple_query("SHOW timezone").await.expect("show");
        assert_eq!(single_text(&show), "UTC");
        let utc = s
            .simple_query("SELECT TIMESTAMPTZ '2024-01-15 12:00:00+00'")
            .await
            .expect("select utc");
        assert_eq!(single_text(&utc), "2024-01-15 12:00:00+00");

        // SET TIME ZONE (autocommit) persists and feeds eval_ctx().
        s.simple_query("SET TIME ZONE 'America/New_York'")
            .await
            .expect("set tz");
        let show_ny = s.simple_query("SHOW timezone").await.expect("show ny");
        assert_eq!(single_text(&show_ny), "America/New_York");
        let ny = s
            .simple_query("SELECT TIMESTAMPTZ '2024-01-15 12:00:00+00'")
            .await
            .expect("select ny");
        assert_eq!(single_text(&ny), "2024-01-15 07:00:00-05");

        // A SET inside a transaction reverts on ROLLBACK.
        s.simple_query("BEGIN").await.expect("begin");
        s.simple_query("SET TIME ZONE 'UTC'")
            .await
            .expect("set utc");
        let inside = s.simple_query("SHOW timezone").await.expect("show inside");
        assert_eq!(single_text(&inside), "UTC");
        s.simple_query("ROLLBACK").await.expect("rollback");
        let after = s.simple_query("SHOW timezone").await.expect("show after");
        assert_eq!(single_text(&after), "America/New_York");

        // A SET inside a transaction persists on COMMIT.
        s.simple_query("BEGIN").await.expect("begin2");
        s.simple_query("SET TIME ZONE 'UTC'")
            .await
            .expect("set utc2");
        s.simple_query("COMMIT").await.expect("commit");
        let committed = s
            .simple_query("SHOW timezone")
            .await
            .expect("show committed");
        assert_eq!(single_text(&committed), "UTC");
    }

    /// SP37: SET LOCAL is always reverted at end-of-transaction; an unknown
    /// parameter is 42704; a bad zone is 22023.
    #[tokio::test]
    async fn set_local_reverts_and_errors_have_right_sqlstate() {
        let engine = SqlEngine::new();
        let mut s = engine.connect();

        s.simple_query("BEGIN").await.expect("begin");
        s.simple_query("SET LOCAL TIME ZONE 'America/New_York'")
            .await
            .expect("set local");
        let inside = s.simple_query("SHOW timezone").await.expect("show local");
        assert_eq!(single_text(&inside), "America/New_York");
        // COMMIT drops a LOCAL override (never promoted).
        s.simple_query("COMMIT").await.expect("commit");
        let after = s.simple_query("SHOW timezone").await.expect("show after");
        assert_eq!(single_text(&after), "UTC");

        // Unknown parameter → 42704.
        let unknown = s
            .simple_query("SET nonexistent_param = 'x'")
            .await
            .expect_err("unknown param");
        assert_eq!(unknown.code, "42704");
        let unknown_show = s
            .simple_query("SHOW nonexistent_param")
            .await
            .expect_err("unknown show");
        assert_eq!(unknown_show.code, "42704");

        // Invalid zone → 22023.
        let bad = s
            .simple_query("SET timezone = 'Not/AZone'")
            .await
            .expect_err("bad zone");
        assert_eq!(bad.code, "22023");
    }

    /// Every expected string was read off `PostgreSQL` 18.4 under
    /// `DateStyle = 'Postgres, MDY'`, the setting `pg_regress` runs with.
    ///
    /// The legacy IANA link names (`PST8PDT`, `US/Pacific`, `Navajo`, …) are the
    /// point of the table: `PostgreSQL` carries them because it ships its own
    /// copy of the zone database, and gres matches only because it resolves
    /// through the bundled copy rather than the host's `/usr/share/zoneinfo`,
    /// which many distributions trim.
    #[tokio::test]
    async fn timezone_setting_accepts_and_renders_the_postgresql_zone_vocabulary() {
        let cases: &[(&str, &str, &str)] = &[
            // zone, winter render, summer render
            (
                "UTC",
                "Thu Jan 01 00:00:00 1970 UTC",
                "Sun Jul 01 12:00:00 2001 UTC",
            ),
            (
                "America/Los_Angeles",
                "Wed Dec 31 16:00:00 1969 PST",
                "Sun Jul 01 05:00:00 2001 PDT",
            ),
            (
                "Europe/Rome",
                "Thu Jan 01 01:00:00 1970 CET",
                "Sun Jul 01 14:00:00 2001 CEST",
            ),
            (
                "EST",
                "Wed Dec 31 19:00:00 1969 EST",
                "Sun Jul 01 07:00:00 2001 EST",
            ),
            (
                "PST8PDT",
                "Wed Dec 31 16:00:00 1969 PST",
                "Sun Jul 01 05:00:00 2001 PDT",
            ),
            (
                "EST5EDT",
                "Wed Dec 31 19:00:00 1969 EST",
                "Sun Jul 01 08:00:00 2001 EDT",
            ),
            (
                "CST6CDT",
                "Wed Dec 31 18:00:00 1969 CST",
                "Sun Jul 01 07:00:00 2001 CDT",
            ),
            (
                "MST7MDT",
                "Wed Dec 31 17:00:00 1969 MST",
                "Sun Jul 01 06:00:00 2001 MDT",
            ),
            (
                "US/Pacific",
                "Wed Dec 31 16:00:00 1969 PST",
                "Sun Jul 01 05:00:00 2001 PDT",
            ),
            (
                "US/Eastern",
                "Wed Dec 31 19:00:00 1969 EST",
                "Sun Jul 01 08:00:00 2001 EDT",
            ),
            (
                "Navajo",
                "Wed Dec 31 17:00:00 1969 MST",
                "Sun Jul 01 06:00:00 2001 MDT",
            ),
            (
                "Japan",
                "Thu Jan 01 09:00:00 1970 JST",
                "Sun Jul 01 21:00:00 2001 JST",
            ),
            (
                "GB",
                "Thu Jan 01 01:00:00 1970 BST",
                "Sun Jul 01 13:00:00 2001 BST",
            ),
        ];

        let engine = SqlEngine::new();
        let mut s = engine.connect();
        s.simple_query("SET DateStyle = 'Postgres, MDY'")
            .await
            .expect("datestyle");

        for &(zone, winter, summer) in cases {
            s.simple_query(&format!("SET timezone = '{zone}'"))
                .await
                .unwrap_or_else(|e| panic!("SET timezone = '{zone}': {e:?}"));
            let shown = s.simple_query("SHOW timezone").await.expect("show");
            assert!(single_text(&shown) == zone, "SHOW timezone for {zone}");

            let rendered = s
                .simple_query("SELECT timestamptz '1970-01-01 00:00:00+00'")
                .await
                .expect("winter render");
            assert!(single_text(&rendered) == winter, "winter render for {zone}");

            let rendered = s
                .simple_query("SELECT timestamptz '2001-07-01 12:00:00+00'")
                .await
                .expect("summer render");
            assert!(single_text(&rendered) == summer, "summer render for {zone}");
        }
    }

    /// A zone-bearing literal reaches the decoder lowercased, so the legacy link
    /// names have to resolve case-insensitively there too — and a name the
    /// bundled database does not carry stays an error.
    #[tokio::test]
    async fn zone_bearing_literals_resolve_legacy_link_names() {
        let engine = SqlEngine::new();
        let mut s = engine.connect();
        s.simple_query("SET DateStyle = 'Postgres, MDY'")
            .await
            .expect("datestyle");
        s.simple_query("SET timezone = 'UTC'")
            .await
            .expect("timezone");

        // Every expectation is `PostgreSQL` 18.4's rendering of the same literal.
        for (literal, expected) in [
            ("PST8PDT", "Sun Jul 01 19:00:00 2001 UTC"),
            ("us/pacific", "Sun Jul 01 19:00:00 2001 UTC"),
            ("America/Los_Angeles", "Sun Jul 01 19:00:00 2001 UTC"),
            ("Navajo", "Sun Jul 01 18:00:00 2001 UTC"),
            ("navajo", "Sun Jul 01 18:00:00 2001 UTC"),
            ("Japan", "Sun Jul 01 03:00:00 2001 UTC"),
            ("Turkey", "Sun Jul 01 09:00:00 2001 UTC"),
            // A default-set abbreviation still wins over the same-spelled zone.
            ("EST", "Sun Jul 01 17:00:00 2001 UTC"),
        ] {
            let rendered = s
                .simple_query(&format!(
                    "SELECT timestamptz '2001-07-01 12:00:00 {literal}'"
                ))
                .await
                .unwrap_or_else(|e| panic!("literal in {literal}: {e:?}"));
            assert!(single_text(&rendered) == expected, "literal in {literal}");
        }

        // A punctuated name the database does not carry is 22023; an unknown
        // bare word never became a zone at all, so it stays 22007. Both codes
        // are PostgreSQL 18.4's.
        let bad = s
            .simple_query("SELECT timestamptz '2001-07-01 12:00:00 Not/AZone'")
            .await
            .expect_err("unknown punctuated zone");
        assert!(bad.code == "22023");
        let bad = s
            .simple_query("SELECT timestamptz '2001-07-01 12:00:00 Navajoo'")
            .await
            .expect_err("unknown bare word");
        assert!(bad.code == "22007");
    }

    #[tokio::test]
    async fn common_gucs_support_preamble_show_reset_and_discard() {
        let engine = SqlEngine::new();
        let mut s = engine.connect();

        s.simple_query("SET application_name = 'sqlx'")
            .await
            .expect("application_name");
        s.simple_query("SET client_encoding = 'UTF8'")
            .await
            .expect("client_encoding");
        s.simple_query("SET standard_conforming_strings = on")
            .await
            .expect("standard_conforming_strings");
        s.simple_query("SET search_path = public")
            .await
            .expect("search_path");
        s.simple_query("SET statement_timeout = 0")
            .await
            .expect("statement_timeout");

        assert_eq!(
            single_text(&s.simple_query("SHOW application_name").await.expect("show")),
            "sqlx"
        );
        assert_eq!(
            single_text(&s.simple_query("SHOW client_encoding").await.expect("show")),
            "UTF8"
        );
        for encoding in ["LATIN1", "EUC_JP"] {
            s.simple_query(&format!("SET client_encoding = {encoding}"))
                .await
                .unwrap_or_else(|error| panic!("{encoding}: {error:?}"));
            assert!(
                single_text(&s.simple_query("SHOW client_encoding").await.expect("show"))
                    == encoding
            );
        }
        assert!(
            s.simple_query("SET client_encoding = NO_SUCH_ENCODING")
                .await
                .is_err()
        );

        s.simple_query("RESET ALL").await.expect("reset all");
        assert_eq!(
            single_text(&s.simple_query("SHOW application_name").await.expect("show")),
            ""
        );

        s.simple_query("SET application_name = 'psql' ")
            .await
            .expect("set again");
        s.simple_query("DISCARD ALL").await.expect("discard all");
        assert_eq!(
            single_text(&s.simple_query("SHOW application_name").await.expect("show")),
            ""
        );
    }

