    #[test]
    fn extra_float_digits_matches_postgres_integer_guc_input() {
        assert_eq!(guc_default("extra_float_digits"), "1");
        assert_eq!(guc_vartype("extra_float_digits"), "integer");

        for (input, expected) in [
            ("-15", "-15"),
            ("3", "3"),
            ("  +2  ", "2"),
            ("1.4", "1"),
            ("1.6", "2"),
            ("1.5", "2"),
            ("-1.5", "-2"),
            ("0x2", "2"),
            ("+0x2", "2"),
            ("0b10", "2"),
        ] {
            assert_eq!(
                canonical_guc_value("extra_float_digits", input)
                    .expect("accepted by PostgreSQL 18"),
                expected
            );
        }
        // Out of range and unreadable are different 22023s, with different
        // messages, exactly as PostgreSQL reports them.
        for input in ["-16", "4", "010"] {
            assert!(matches!(
                canonical_guc_value("extra_float_digits", input),
                Err(ExecError::GucValueOutOfRange(_))
            ));
        }
        for input in ["nope", "0o2", "0_1"] {
            assert!(matches!(
                canonical_guc_value("extra_float_digits", input),
                Err(ExecError::InvalidGucValue { .. })
            ));
        }
    }

