    #[tokio::test]
    async fn current_setting_and_set_config_follow_transaction_scope() {
        let engine = SqlEngine::new();
        let mut s = engine.connect();

        let initial = s
            .simple_query("SELECT current_setting('application_name')")
            .await
            .expect("current_setting");
        assert_eq!(single_text(&initial), "");

        let missing = s
            .simple_query("SELECT current_setting('no_such_setting', true)")
            .await
            .expect("missing ok");
        let [crabka_pgwire::engine::QueryResult::Rows { rows, .. }] = &missing[..] else {
            panic!("expected rows, got {missing:?}");
        };
        assert!(rows[0][0].is_none());

        let set = s
            .simple_query("SELECT set_config('application_name', 'from-func', false)")
            .await
            .expect("set_config");
        assert_eq!(single_text(&set), "from-func");
        assert_eq!(
            single_text(&s.simple_query("SHOW application_name").await.expect("show")),
            "from-func"
        );

        s.simple_query("BEGIN").await.expect("begin");
        s.simple_query("SELECT set_config('application_name', 'local-only', true)")
            .await
            .expect("set local");
        assert_eq!(
            single_text(&s.simple_query("SHOW application_name").await.expect("show")),
            "local-only"
        );
        s.simple_query("COMMIT").await.expect("commit");
        assert_eq!(
            single_text(&s.simple_query("SHOW application_name").await.expect("show")),
            "from-func"
        );
    }

    #[tokio::test]
    async fn plpgsql_expression_workers_install_the_session_guc_runtime() {
        let engine = SqlEngine::new();
        let mut session = engine.connect();
        session
            .simple_query(
                "CREATE FUNCTION plpgsql_work_mem() RETURNS text LANGUAGE plpgsql AS \
                 $$ BEGIN RETURN current_setting('work_mem'); END $$",
            )
            .await
            .expect("create function");
        session
            .simple_query("SET work_mem = '3MB'")
            .await
            .expect("set work_mem");

        session
            .simple_query(
                "CREATE FUNCTION plpgsql_work_mem_subquery() RETURNS text LANGUAGE plpgsql AS \
                 $$ BEGIN RETURN (SELECT current_setting('work_mem')); END $$",
            )
            .await
            .expect("create subquery function");
        session
            .simple_query(
                "CREATE FUNCTION plpgsql_set_config() RETURNS text LANGUAGE plpgsql AS \
                 $$ BEGIN RETURN set_config('application_name', 'from-plpgsql', false); END $$",
            )
            .await
            .expect("create set_config function");

        assert_eq!(
            single_text(
                &session
                    .simple_query("SELECT plpgsql_work_mem()")
                    .await
                    .expect("PL/pgSQL current_setting")
            ),
            "3MB"
        );
        assert_eq!(
            single_text(
                &session
                    .simple_query("SELECT plpgsql_work_mem_subquery()")
                    .await
                    .expect("PL/pgSQL subquery current_setting")
            ),
            "3MB"
        );
        assert_eq!(
            single_text(
                &session
                    .simple_query("SELECT plpgsql_set_config()")
                    .await
                    .expect("PL/pgSQL set_config")
            ),
            "from-plpgsql"
        );
        assert_eq!(
            single_text(
                &session
                    .simple_query("SHOW application_name")
                    .await
                    .expect("session mutation")
            ),
            "from-plpgsql"
        );
    }

